<?php
require __DIR__.'/config.php';
require_admin();
$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=$_POST['action']??'';
 try{
  if($action==='status'){ $id=(int)$_POST['order_id'];$status=$_POST['status']??'Pending';$allowed=['Pending','Preparing','Ready for pickup','Completed','Cancelled'];if(!in_array($status,$allowed,true))throw new RuntimeException('Invalid order status.');$s=$pdo->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$status,$id]);flash('Order status updated.'); }
  elseif($action==='save_product'){ $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$cat=trim($_POST['category']??'');$desc=trim($_POST['description']??'');$emoji=trim($_POST['emoji']??'🍽️');$price=(float)($_POST['price']??0);if($name===''||$cat===''||$price<=0)throw new RuntimeException('Enter a product name, category, and price above zero.');if($id){$s=$pdo->prepare('UPDATE products SET name=?,category=?,description=?,emoji=?,price=? WHERE id=?');$s->execute([$name,$cat,$desc,$emoji,$price,$id]);}else{$s=$pdo->prepare('INSERT INTO products(name,category,description,emoji,price) VALUES(?,?,?,?,?)');$s->execute([$name,$cat,$desc,$emoji,$price]);}flash('Product saved.'); }
  elseif($action==='toggle_product'){ $s=$pdo->prepare('UPDATE products SET is_available=IF(is_available=1,0,1) WHERE id=?');$s->execute([(int)$_POST['id']]);flash('Product availability changed.'); }
 }catch(RuntimeException $ex){flash($ex->getMessage(),'error');}
 redirect('admin.php'.(!empty($_POST['section'])?'?section='.urlencode($_POST['section']):''));
}
$section=$_GET['section']??'overview';$flash=get_flash();
$stats=['products'=>(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(),'orders'=>(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'pending'=>(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status IN ('Pending','Preparing','Ready for pickup')")->fetchColumn(),'users'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn()];
$orders=$pdo->query('SELECT o.*,u.full_name,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC LIMIT 150')->fetchAll();
$products=$pdo->query('SELECT * FROM products ORDER BY category,name')->fetchAll();
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin dashboard · PHINMA AU Canteen</title><link rel="stylesheet" href="style.css"></head><body><header class="nav"><div class="wrap"><a class="brand" href="admin.php">PHINMA AU · ADMIN</a><div><a href="admin.php">Dashboard</a><a href="admin.php?section=orders">Orders</a><a href="admin.php?section=products">Products</a><a href="logout.php">Logout</a></div></div></header><main class="wrap">
<?php if($flash): ?><div class="alert <?=$flash['type']==='error'?'error':''?>"><?=e($flash['message'])?></div><?php endif; ?>
<h1>Admin dashboard</h1><p class="muted">Signed in as <?=e(current_user()['email'])?>. Manage canteen products and student orders.</p>
<div class="grid"><?php foreach([['Products',$stats['products']],['All orders',$stats['orders']],['Active orders',$stats['pending']],['Student accounts',$stats['users']]] as [$label,$value]): ?><div class="panel"><p class="muted"><?=$label?></p><div class="total"><?=$value?></div></div><?php endforeach; ?></div>
<?php if($section==='products'): ?><div class="panel"><h2><?=$edit?'Edit product':'Add product'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="section" value="products"><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><div class="grid"><div class="field"><label>Name</label><input name="name" required value="<?=e($edit['name']??'')?>"></div><div class="field"><label>Category</label><select name="category"><?php foreach(['Rice Meals','Snacks','Drinks','Desserts','Other'] as $c): ?><option <?=($edit['category']??'')===$c?'selected':''?>><?=$c?></option><?php endforeach; ?></select></div><div class="field"><label>Price (PHP)</label><input type="number" name="price" min="0.01" step="0.01" required value="<?=e((string)($edit['price']??''))?>"></div><div class="field"><label>Emoji</label><input name="emoji" maxlength="16" value="<?=e($edit['emoji']??'🍽️')?>"></div></div><div class="field"><label>Description</label><input name="description" value="<?=e($edit['description']??'')?>"></div><button>Save product</button> <?php if($edit): ?><a class="btn secondary" href="admin.php?section=products">Cancel edit</a><?php endif; ?></form></div>
<div class="panel table-wrap"><h2>Menu products</h2><table><thead><tr><th>Item</th><th>Category</th><th>Price</th><th>Availability</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?=e($p['emoji'].' '.$p['name'])?></td><td><?=e($p['category'])?></td><td><?=money($p['price'])?></td><td><?=$p['is_available']?'Available':'Hidden'?></td><td><a class="btn secondary" href="admin.php?section=products&edit=<?=$p['id']?>">Edit</a> <form class="inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_product"><input type="hidden" name="section" value="products"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="danger"><?=$p['is_available']?'Hide':'Show'?></button></form></td></tr><?php endforeach; ?></tbody></table></div>
<?php else: ?><div class="panel table-wrap"><div class="row"><h2><?= $section==='orders'?'Order management':'Recent orders' ?></h2><a class="btn secondary" href="admin.php?section=products">Manage menu</a></div><table><thead><tr><th>Order</th><th>Student</th><th>Items</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#<?=$o['id']?><br><small><?=e($o['created_at'])?></small></td><td><?=e($o['full_name'])?><br><small><?=e($o['email'])?></small></td><td><?php $it=$pdo->prepare('SELECT product_name,quantity FROM order_items WHERE order_id=?');$it->execute([$o['id']]);foreach($it as $i)echo e($i['product_name']).' × '.(int)$i['quantity'].'<br>'; ?></td><td><?=money($o['total'])?></td><td><?=e($o['payment_method'])?></td><td><span class="badge <?=e($o['status'])?>"><?=e($o['status'])?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="section" value="<?=e($section)?>"><select name="status"><?php foreach(['Pending','Preparing','Ready for pickup','Completed','Cancelled'] as $st): ?><option <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach; ?></select><button style="margin-top:5px">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</main><div class="footer">Admin tools · Use responsibly and protect student data.</div></body></html>
